ALTER TABLE "pull_requests" ADD CONSTRAINT "pull_requests_target_check" CHECK (("pull_requests"."target_type" = 'PHOTO' and "pull_requests"."photo_public_id" is not null and "pull_requests"."photo_version" is not null and "pull_requests"."photo_version" > 0 and "pull_requests"."prompt_id" is null and "pull_requests"."prompt_answer" is null) or ("pull_requests"."target_type" = 'PROMPT' and "pull_requests"."prompt_id" is not null and "pull_requests"."prompt_answer" is not null and "pull_requests"."photo_public_id" is null and "pull_requests"."photo_version" is null));